import socket,struct,random
def q(name, qtype=1):
    tid=random.randint(0,65535)
    hdr=struct.pack(">HHHHHH",tid,0x0100,1,0,0,0)
    qn=b"".join(bytes([len(p)])+p.encode() for p in name.split("."))+b"\0"
    pkt=hdr+qn+struct.pack(">HH",qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(1.5)
    try:
        s.sendto(pkt,("127.0.0.11",53)); d,_=s.recvfrom(512)
        anc=struct.unpack(">H",d[6:8])[0]
        print(name,"rcode",d[3]&0xF,"ancount",anc)
